    const before = await snapshot(root);
    const runtimeBefore = await snapshot(f.runtimeRoot);
    const mutations = [
      vi.spyOn(fs, 'mkdir'),
      vi.spyOn(fs, 'writeFile'),
      vi.spyOn(fs, 'rename'),
      vi.spyOn(fs, 'rm'),
      vi.spyOn(fs, 'unlink'),
