          ? await runNativeCli(['new', 'owned', '--project-root', projectRoot, '--json'])
          : await runClassicCli(
              ['state', 'init', 'owned', 'full', '--isolation', 'current'],
              undefined,
              { projectRoot, invocationCwd: projectRoot },
            );
